insert into t_gen_table (msn, name, comment, entity_name, service_name, mapper_name
    , service_impl_name, controller_name, xml_name, remark, view_type, prefix, db_name, disabled) VALUES

    (#{item.msn},#{item.name},#{item.comment},#{item.entityName},#{item.serviceName},#{item.mapperName}
    ,#{item.serviceImplName},#{item.controllerName},#{item.xmlName},#{item.remark},#{item.viewType}
    ,#{item.prefix}, #{item.dbName}, #{item.disabled})
